  # drain boot noise
  while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 100 }
  function Send-Nsh($cmd) {
    $port.WriteLine($cmd)
    Start-Sleep -Milliseconds 1200
    $buf = ""
    $deadline = (Get-Date).AddSeconds(6)
    while ((Get-Date) -lt $deadline) {
      if ($port.BytesToRead -gt 0) { $buf += $port.ReadExisting() }
      if ($buf -match "nsh>" -or $buf -match "vela>") { break }
      Start-Sleep -Milliseconds 150
    }
    return $buf
  }
  $out = Send-Nsh "help"
  Write-Output "=== HELP (head) ==="
  Write-Output ($out.Substring(0, [Math]::Min(800, $out.Length)))
