input.command:
sleep 4 && powershell.exe -NoProfile -Command '
$port = New-Object System.IO.Ports.SerialPort
$port.PortName = "COM3"; $port.BaudRate = 115200; $port.ReadTimeout = 8000; $port.NewLine = "`n"
$results = @()
try {
  $port.Open()
  Start-Sleep -Milliseconds 1200
  while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 80 }
  function Send($cmd, [int]$waitSec = 12) {
    $port.DiscardInBuffer()
    $port.WriteLine($cmd)
    Start-Sleep -Milliseconds 500
    $buf = ""
    $deadline = (Get-Date).AddSeconds($waitSec)
    while ((Get-Date) -lt $deadline) {
      if ($port.BytesToRead -gt 0) { $buf += $port.ReadExisting() }
      if ($buf -match "nsh>" -or $buf -match "vela>") {
        if ($buf -match "nsh>\s*$" -or $buf -match "vela>\s*$" -or ($buf -match "nsh>" -and $buf.Length -gt 20)) { break }
      }
      Start-Sleep -Milliseconds 150
    }
    $script:results += [pscustomobject]@{Cmd=$cmd; Out=($buf -replace "`e\[K","")}
    return $buf
  }
  Send "mount" 8
  Send "echo stage0-ac2 > /mnt/emmc/vg_ac.txt" 8
  Send "cat /mnt/emmc/vg_ac.txt" 8
  Send "vgrs485 tx" 8
  Send "vgstats inject 1 crc" 8
  Send "vgstats inject 1 timeout" 8
  Send "vgstats dump 1" 8
  Send "vgstats reset 1" 8
  Send "vgmodbus -a 1 -r 0 -c 2 -n 5 -i 1" 35
  Send "vgstats dump 1" 8
  Send "vgstats reset 2" 8
  Send "vgmodbus -a 2 -r 2 -c 1 -n 5 -i 1" 35
  Send "vgstats dump 2" 8
  Send "vgstats reset 3" 8
  Send "vgmodbus -a 3 -r 0 -c 4 -n 5 -i 1" 35
  Send "vgstats dump 3" 8
  Send "vgcfg dump" 8
} catch {
  Write-Output "ERR: $($_.Exception.Message)"
} finally {
  if ($port.IsOpen) { $port.Close() }
}
foreach ($r in $results) {
  Write-Output "`n===== $($r.Cmd) ====="
  $lines = ($r.Out -split "`n") | Where-Object { $_ -match "^(addr=|read |vgstats:|vgcfg:|stage0|vgrs485:|mount|/dev|/mnt|read failed|vgmodbus:)" -or $_ -match "mmcsd|emmc|PASS|FAIL|FACTORY|OK seq" }
  if ($lines) { $lines | ForEach-Object { Write-Output $_ } } else { Write-Output ($r.Out.Substring([Math]::Max(0,$r.Out.Length-400))) }
}
' 2>&1
